require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../services/PersonalPlannerService.php';Auth::requireLogin();$u=Auth::user();$period=in_array($_GET['period']??'', ['daily','weekly','monthly'],true)?$_GET['period']:'monthly';$anchor=trim((string)($_GET['date']??date('Y-m-d')));try{$d=new DateTimeImmutable($anchor);if($period==='daily'){$from=$to=$d->format('Y-m-d');}elseif($period==='weekly'){$offset=((int)$d->format('w')+1)%7;$from=$d->modify("-{$offset} days")->format('Y-m-d');$to=(new DateTimeImmutable($from))->modify('+6 days')->format('Y-m-d');}else{$j=JalaliDate::toJalali($d->format('Y-m-d'));[$jy,$jm]=array_map('intval',explode('/',$j));$from=JalaliDate::toGregorian(sprintf('%04d/%02d/01',$jy,$jm));$to=JalaliDate::toGregorian(sprintf('%04d/%02d/%02d',$jy,$jm,JalaliDate::monthLength($jy,$jm)));}$report=PersonalPlannerService::report((int)$u['id'],$from,$to);}catch(Throwable $e){error_log('Planner report: '.$e->getMessage());$from=$to=date('Y-m-d');$report=PersonalPlannerService::report((int)$u['id'],$from,$to);}
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="personal-planner-'.date('Ymd-His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['تاریخ','عنوان وظیفه','وضعیت','اولویت','مهم','تکرارشونده','زمان موعد','زمان تکمیل','انتقال‌یافته از','انتقال‌یافته به']);foreach($report['tasks'] as $t)fputcsv($out,[JalaliDate::toJalali($t['task_date']),$t['title'],$t['status'],$t['priority'],(int)$t['is_important']?'بله':'خیر',(int)$t['is_recurring']?'بله':'خیر',$t['due_at'],$t['completed_at'],JalaliDate::toJalali($t['moved_from_date']),JalaliDate::toJalali($t['moved_to_date'])]);fclose($out);exit;}
$pageTitle='گزارش برنامه کاری';require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><h1>گزارش برنامه کاری من</h1><p class="muted">تحلیل شخصی عملکرد از <?=e(JalaliDate::toJalali($from))?> تا <?=e(JalaliDate::toJalali($to))?></p></div><div><a class="btn" href="/admin/personal-planner.php">برنامه کاری</a> <a class="btn btn-primary" href="?period=<?=e($period)?>&date=<?=e($anchor)?>&export=csv">خروجی CSV</a></div></div><form class="card filter-form" method="get"><label>نوع گزارش<select name="period"><option value="daily" <?=$period==='daily'?'selected':''?>>روزانه</option><option value="weekly" <?=$period==='weekly'?'selected':''?>>هفتگی</option><option value="monthly" <?=$period==='monthly'?'selected':''?>>ماهانه</option></select></label><label>تاریخ مبنا<?=app_date_input('date',$anchor)?></label><button class="btn">نمایش</button></form><div class="stats-grid"><article class="stat-card"><span>کل کارها</span><strong><?=format_number($report['total'])?></strong></article><article class="stat-card"><span>انجام‌شده</span><strong><?=format_number($report['done'])?></strong></article><article class="stat-card"><span>عقب‌افتاده</span><strong><?=format_number($report['overdue'])?></strong></article><article class="stat-card"><span>انتقال‌یافته</span><strong><?=format_number($report['moved'])?></strong></article><article class="stat-card"><span>درصد انجام</span><strong><?=format_number($report['percent'])?>٪</strong></article></div><section class="card"><h2>روند روزانه</h2><div class="planner-report-bars"><?php foreach($report['daily'] as $day):?><article><span><?=e($day['date_jalali'])?></span><div><i style="width:<?=(int)$day['percent']?>%"></i></div><b><?=(int)$day['percent']?>٪</b></article><?php endforeach?></div></section><section class="card"><h2>جزئیات وظایف</h2><div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>عنوان</th><th>وضعیت</th><th>اولویت</th><th>تکرار</th></tr></thead><tbody><?php foreach($report['tasks'] as $t):?><tr><td><?=e(JalaliDate::toJalali($t['task_date']))?></td><td><?=e($t['title'])?></td><td><?=e($t['status'])?></td><td><?=e($t['priority'])?></td><td><?=(int)$t['is_recurring']?'بله':'خیر'?></td></tr><?php endforeach?><?php if(!$report['tasks']):?><tr><td colspan="5">در این بازه کاری ثبت نشده است.</td></tr><?php endif?></tbody></table></div></section><style>.planner-report-bars{display:grid;gap:8px}.planner-report-bars article{display:grid;grid-template-columns:100px 1fr 50px;align-items:center;gap:10px}.planner-report-bars article div{height:9px;background:#edf1f4;border-radius:9px;overflow:hidden}.planner-report-bars i{display:block;height:100%;background:var(--primary,#087f8c)}</style><?php require __DIR__.'/../views/partials/admin-footer.php';?>
